// @font-face rules for the bundled IBM Plex, shared by every theme's CSS.
const FONT_FACES = "@font-face { font-family: 'Asgard Sans'; font-weight: 400 600; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }\n@font-face { font-family: 'Asgard Mono'; font-weight: 400; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }\n@font-face { font-family: 'Asgard Mono'; font-weight: 500; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }\n@font-face { font-family: 'Asgard Mono'; font-weight: 600; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }\n"

const SIDEBAR_ZONE = '[data-tree-group]:has([data-slot="sidebar"])'


function cssFor(THEME) {
  const V = THEME.vars
  const ART = THEME.art
  // Prefix match: picking an accent colour renames the active theme to `<name>-accent-<hex>`.
  const T = `:root[data-hermes-theme^="${THEME.name}"]`
  // Painted art keeps its own antialiasing; dithered art shows one dot per 2 CSS px.
  const IR = THEME.render === 'smooth' ? 'auto' : 'pixelated'

  // A theme's own lettering for the wordmark; a theme without one keeps the app's Collapse.
  const D = THEME.display
  const display = D
    ? `@font-face { font-family: '${D.family}'; font-weight: ${D.weight}; font-style: normal; font-display: block; src: url(${D.src}) format('woff2'); }
${T} .wordmark { font-family: '${D.family}', 'Collapse', var(--font-sans) !important; font-weight: ${D.weight} !important; letter-spacing: ${D.tracking} !important; font-synthesis: none; }
`
    : ''

  return `${FONT_FACES}${display}
${T} {
  --pack-ink: ${V.ink};
  --pack-dim: ${V.dim};
  --pack-rule: color-mix(in srgb, ${V.rule} 32%, transparent);
  --pack-dots: radial-gradient(circle at center, ${V.wordmarkDots} 0.55px, transparent 1px);
  --pack-art-floor: 250px;
}

/* ── Sidebar art ─────────────────────────────────────────────────────────── */

${T} ${SIDEBAR_ZONE} > [data-panel-header] {
  position: relative;
  height: 262px !important;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header]::before {
  content: '';
  position: absolute;
  /* below the title bar row, so the window controls never sit on the art; the
     bottom stays put, so the fade still ends above the tabs */
  inset: 20px 0 18px 0;
  background: url("${ART.top}") center 0 / 320px auto no-repeat;
  image-rendering: ${IR};
  /* the art's flat top edge fades in instead of cutting across the head */
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 9%, #000 72%, transparent);
  mask-image: linear-gradient(to bottom, transparent, #000 9%, #000 72%, transparent);
  pointer-events: none;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header] > [data-window-drag-handle] {
  z-index: 1;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header] > [data-zone-tabstrip] {
  z-index: 1;
  background: transparent;
  padding-inline: 14px;
  gap: 10px;
  /* inactive tabs fill with this colour: clear it so the art shows through them, as through the active tab */
  --pane-tab-strip-bg: transparent;
}

${T} [data-tree-group]:not(:has([data-slot="sidebar"])) > [data-panel-header] > [data-zone-tabstrip] {
  padding-left: 10px;
}

${T} [data-slot="sidebar"] {
  position: relative;
  isolation: isolate;
}

${T} [data-slot="sidebar"]::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: auto 0 0 0;
  height: var(--pack-art-floor);
  background: url("${ART.bottom}") center bottom / 320px auto no-repeat;
  image-rendering: ${IR};
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 40%);
  mask-image: linear-gradient(to bottom, transparent, #000 40%);
  pointer-events: none;
}

/* the session list stops where the collage starts fading in, and scrolls above it */
${T} [data-slot="sidebar"] [data-slot="sidebar-content"] > *:last-child {
  padding-bottom: var(--pack-art-floor);
}

/* ── Shorter windows: smaller art, never cropped ─────────────────────────── */

/* Below 1080px the full-size art leaves only a handful of sessions on screen,
   so it steps down instead: the bust to 240px wide and the collage to 160px,
   then the collage goes, then the bust drops to 160px. Each step shows the
   whole image, and the header keeps the same 22px under the bust. */
@media (max-height: 1079px) {
  ${T} {
    --pack-art-floor: 125px;
  }

  ${T} ${SIDEBAR_ZONE} > [data-panel-header] {
    height: 202px !important;
  }

  ${T} ${SIDEBAR_ZONE} > [data-panel-header]::before {
    background-size: 240px auto;
    background-position: right top;
  }

  ${T} [data-slot="sidebar"]::before {
    background-size: 160px auto;
  }
}

@media (max-height: 859px) {
  ${T} {
    --pack-art-floor: 0px;
  }
}

@media (max-height: 719px) {
  ${T} ${SIDEBAR_ZONE} > [data-panel-header] {
    height: 142px !important;
  }

  ${T} ${SIDEBAR_ZONE} > [data-panel-header]::before {
    background-size: 160px auto;
  }
}

/* ── Tabs: mono caps, a carved shield when active ────────────────────────── */

${T} [data-slot="pane-tab"],
${T} [data-tree-tab] {
  font-family: var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 0 !important;
  box-shadow: none !important;
}

${T} [data-slot="pane-tab"][data-active="true"],
${T} [data-tree-tab][data-active="true"] {
  color: var(--pack-ink);
  background: transparent !important;
  border: 1px solid var(--pack-rule) !important;
  border-radius: 4px 4px 14px 14px / 4px 4px 11px 11px !important;
  box-shadow: inset 0 0 0 2px ${THEME.colors.background}, inset 0 0 0 3px color-mix(in srgb, var(--pack-rule) 45%, transparent) !important;
}

${T} [data-slot="pane-tab"][data-active="true"]::after,
${T} [data-tree-tab][data-active="true"]::after {
  display: none !important;
}

${T} [data-slot="pane-tab"][data-active="false"] {
  color: var(--pack-dim);
}

/* ── Carved rules: the double cut lines of a runestone  ───────────────────── */

${T} [data-tree-group][data-window-top] > [data-panel-header] {
  border-bottom: 3px double var(--pack-rule);
}

${T} [data-slot="sidebar"] {
  border-right: 3px double var(--pack-rule) !important;
}

${T} [data-sash-overlap] {
  opacity: 0;
}

${T} [data-slot="composer-surface"] {
  border: 3px double color-mix(in srgb, var(--pack-rule) 70%, transparent) !important;
  border-radius: 10px !important;
  background: ${V.surface} !important;
  box-shadow: none !important;
}

${T} [data-slot="kbd"] {
  font-family: var(--font-mono);
  background: transparent !important;
  border: 1px solid color-mix(in srgb, var(--pack-rule) 70%, transparent) !important;
  color: var(--pack-ink) !important;
}

${T} [data-slot="sidebar-input"],
${T} [data-slot="sidebar"] input[type="search"] {
  border: 0 !important;
  border-bottom: 3px double var(--pack-rule) !important;
  border-radius: 0 !important;
  background: transparent !important;
}

/* ── Empty chat: the carved frieze above the runic band  ────────────────── */

${T} [data-slot="aui_intro"] {
  position: relative;
  isolation: isolate;
  overflow: visible;
}

${T} [data-slot="aui_intro"]::before {
  content: '';
  position: absolute;
  z-index: -1;
  left: 50%;
  bottom: calc(100% - 150px);
  width: 900px;
  height: 450px;
  max-width: 100%;
  transform: translateX(-50%);
  background: url("${ART.hero}") center bottom / contain no-repeat;
  image-rendering: ${IR};
  pointer-events: none;
}

/* register lines framing the hero band */
${T} [data-slot="aui_intro"]::after {
  content: '';
  position: absolute;
  z-index: -1;
  left: 4%;
  right: 4%;
  top: 40px;
  height: 120px;
  border: 0;
  height: 0;
  pointer-events: none;
}

${T} .wordmark {
  mix-blend-mode: normal !important;
  position: relative;
}

${T} .wordmark::before {
  content: '';
  position: absolute;
  inset: -0.2em -0.7em -0.16em -0.7em;
  z-index: -1;
  background: var(--pack-rule);
  clip-path: polygon(0.42em 0, calc(100% - 0.42em) 0, 100% 50%, calc(100% - 0.42em) 100%, 0.42em 100%, 0 50%);
  pointer-events: none;
}

${T} .wordmark::after {
  content: '';
  position: absolute;
  inset: calc(-0.2em + 3px) calc(-0.7em + 3px) calc(-0.16em + 3px) calc(-0.7em + 3px);
  z-index: -1;
  background:
    repeating-linear-gradient(115deg, color-mix(in srgb, var(--pack-rule) 70%, transparent) 0 2px, transparent 2px 10px) left top / 100% 7px no-repeat,
    repeating-linear-gradient(65deg, color-mix(in srgb, var(--pack-rule) 70%, transparent) 0 2px, transparent 2px 10px) left bottom / 100% 7px no-repeat,
    ${THEME.colors.background};
  clip-path: polygon(0.42em 0, calc(100% - 0.42em) 0, 100% 50%, calc(100% - 0.42em) 100%, 0.42em 100%, 0 50%);
  pointer-events: none;
}

${T} .wordmark > span:not([aria-hidden]) > span {
  color: transparent;
  background: linear-gradient(180deg, ${V.wordmark.join(', ')});
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 1px ${V.wordmarkShadow});
}

${T} [data-slot="aui_intro"] p:not(.wordmark) {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  letter-spacing: 0.02em;
  line-height: 1.7;
  color: var(--pack-ink);
  max-width: 44ch;
  margin-inline: auto;
}

/* ── Send button: the one bright dot ─────────────────────────────────────── */

${T} [data-slot="composer-surface"] button[data-variant="default"] {
  background: ${V.send} !important;
  color: ${V.sendInk} !important;
}
`
}

const desktopTheme = THEME => ({
  name: THEME.name,
  label: THEME.label,
  description: THEME.description,
  // The same palette for both modes: a theme without darkColors gets a synthesized
  // light palette in light mode, which would put the art on the wrong ground.
  colors: THEME.colors,
  darkColors: THEME.colors,
  typography: THEME.typography,
  terminal: THEME.terminal,
  darkTerminal: THEME.terminal,
  customCSS: cssFor(THEME)
})

// The terminal skins in cli/skins are named `asgard-<god>`. Hermes shares the
// active skin with Desktop, and Desktop prefers a skin over a plugin theme, so a
// terminal `/skin asgard-loki` would paint Desktop with the skin's palette
// alone. Whenever that skin becomes the active theme, switch to the god's full
// theme instead. This only changes Desktop's own pick; the terminal keeps its skin.
const TERMINAL_SKIN_PREFIX = 'asgard-'

function followTerminalSkins() {
  const root = document.documentElement
  const gods = new Set(THEMES.map(THEME => THEME.name))

  const follow = () => {
    const active = root.dataset.hermesTheme ?? ''
    const god = active.startsWith(TERMINAL_SKIN_PREFIX) ? active.slice(TERMINAL_SKIN_PREFIX.length) : ''

    if (gods.has(god)) {
      requestTheme(god)
    }
  }

  const observer = new MutationObserver(follow)
  observer.observe(root, { attributes: true, attributeFilter: ['data-hermes-theme'] })
  follow()

  return () => observer.disconnect()
}

const PLUGIN = {"id": "asgard", "name": "Asgard"}

export default {
  id: PLUGIN.id,
  name: PLUGIN.name,
  register(ctx) {
    ctx.registerMany(THEMES.map(THEME => ({ id: THEME.name, area: THEMES_AREA, data: desktopTheme(THEME) })))
    ctx.onDispose(followTerminalSkins())
  }
}
